columnDataChange.newValue:
async (process, view) => {
  const HIDE_POPUP_PROPERTY = 'APRM_MATCHSTATEMENT_HIDE_PARTIALMATCH_POPUP';
  const NO_RECORD_LABEL = 'APRM_SELECT_RECORD_ERROR';
  const SPLIT_CONFIRM_LABEL = 'APRM_SplitBankStatementLineConfirm';

  const formatAmount = (amount) =>
    OB.Utilities.Number.JSToOBMasked(
      amount,
      OB.Format.defaultNumericMask,
      OB.Format.defaultDecimalSymbol,
      OB.Format.defaultGroupingSymbol,
      OB.Format.defaultGroupingSize
    );

  const contextInfo = view.getContextInfo();
  const trxParameter = contextInfo && contextInfo.findtransactiontomatch;
  const trxSelection = trxParameter && trxParameter._selection;

  if (!trxSelection || !trxSelection[0]) {
    view.messageBar.setMessage(
      isc.OBMessageBar.TYPE_ERROR,
      null,
      OB.I18N.getLabel(NO_RECORD_LABEL)
    );
    return { severity: 'error', text: OB.I18N.getLabel(NO_RECORD_LABEL) };
  }

  const blineAmt = new BigDecimal(String(view.callerField.record.amount));
  let totalTrxAmt = BigDecimal.prototype.ZERO;
  for (const trx of trxSelection) {
    const trxDepositAmt = new BigDecimal(String(trx.depositAmount));
    const trxPaymentAmt = new BigDecimal(String(trx.paymentAmount));
    totalTrxAmt = totalTrxAmt.add(trxDepositAmt.subtract(trxPaymentAmt));
  }

  const splitRequired = totalTrxAmt.compareTo(blineAmt) !== 0;
  if (!splitRequired) {
    return (await view.executeProcess())?.message;
  }

  const hideSplitConfirmation =
    OB.PropertyStore.get(HIDE_POPUP_PROPERTY, view.windowId) === 'Y';
  if (hideSplitConfirmation) {
    return (await view.executeProcess())?.message;
  }

  const confirmed = await confirm(
    OB.I18N.getLabel(SPLIT_CONFIRM_LABEL, [
      formatAmount(blineAmt),
      formatAmount(totalTrxAmt)
    ])
  );
  if (!confirmed) {
    return { severity: 'error', text: '' };
  }
  return (await view.executeProcess())?.message;
}

async (process, view) => {
  const accountsGrid = () => view.theForm.getItem(ACCOUNTS_PARAM).canvas.viewGrid;

  accountsGrid().hide();

  OB.Utilities.Action.set('showVATGrid', () => {
    accountsGrid().show();
  });

  OB.Utilities.Action.set('updateVATTotal', (paramObj) => {
    view.theForm.getItem(AMOUNT_PARAM).setValue(paramObj.amount);
  });

  OB.Utilities.Action.set('updateVATLines', (paramObj) => {
    state.lines = paramObj;
  });
}

const ACCOUNTS_PARAM = 'Accounts';
const AMOUNT_PARAM = 'amount';
const AMOUNT_COLUMN = 'amt';

const state = { lines: null };

const sumAccountAmount = (rowId) => {
  const lines = state.lines;
  if (!lines || !Array.isArray(lines.accounts)) {
    return null;
  }
  const matching = lines.accounts.filter((account) => account.id === rowId);
  if (matching.length === 0) {
    return null;
  }
  return matching.reduce((total, account) => total + parseFloat(account.amt), 0);
};

return { ACCOUNTS_PARAM, AMOUNT_PARAM, AMOUNT_COLUMN, state, sumAccountAmount };

(_process, view) => {
  const INVOICE_DEFAULTS_HANDLER = 'com.smf.jobs.defaults.ProcessInvoicesDefaults';
  const INVOICE_TABLE_ID = '318';
  const form = view.theForm;
  const docActionField = form.getItem('DocAction');
  const voidDateField = form.getItem('VoidDate');
  const voidAcctDateField = form.getItem('VoidAccountingDate');
  const supplierReferenceField = form.getItem('POReference');
  const selectedRecords = view.selectedRecords || [];
  const documentStatuses = [];
  const documentActions = [];

  for (let i = 0; i < selectedRecords.length; i++) {
    const record = selectedRecords[i];
    if (!documentStatuses.includes(record.documentStatus)) {
      documentStatuses.push(record.documentStatus);
    }
    if (!documentActions.includes(record.documentAction)) {
      documentActions.push(record.documentAction);
    }
  }

  voidDateField.hide();
  voidAcctDateField.hide();
  supplierReferenceField.hide();

  OB.RemoteCallManager.call(
    INVOICE_DEFAULTS_HANDLER,
    { documentStatuses: documentStatuses, isProcessing: '', tableId: INVOICE_TABLE_ID },
    {},
    (response, data, request) => {
      const actions = data.actions || [];
      const currentValues = docActionField.getValueMap();
      const newValues = {};

      for (let i = 0; i < actions.length; i++) {
        const action = actions[i];
        const match = currentValues.find((option) => option.value === action || option.id === action);
        if (match) {
          newValues[action] = match.label;
        }
      }

      docActionField.setValueMap(newValues);
      // Avoid setting an action that is on the record(s) but not in the dropdown list.
      if (newValues[documentActions[0]]) {
        docActionField.setValueProgrammatically(documentActions[0]);
      } else {
        docActionField.setValueProgrammatically(docActionField.getFirstOptionValue());
      }
    }
  );
}

async (process, view) => {
  const PRECHECK_HANDLER = "org.openbravo.costing.CostingRuleProcessOnProcessHandler";
  const EXECUTE_HANDLER = "org.openbravo.costing.CostingRuleProcessActionHandler";
  view.messageBar.setMessage("info", null, OB.I18N.getLabel("CostingRuleHelp"));
  const ruleId = view.recordIds && view.recordIds[0];
  const runExecution = async () => {
    const response = await callAction(EXECUTE_HANDLER, { M_Costing_Rule_ID: ruleId }, { queryParams: { processId: process.id } });
    return response.data && response.data.message;
  };
  const precheck = await callAction(PRECHECK_HANDLER, { ruleId });
  const precheckMessage = precheck.data && precheck.data.message;
  const confirmText = precheckMessage && precheckMessage.text;
  if (!confirmText) {
    return await runExecution();
  }
  const accepted = await confirm(confirmText);
  if (!accepted) {
    return { severity: "info", text: "" };
  }
  return await runExecution();
}

// @module-scope
const EAPM_POPUP_ACTION = "EAPM_Popup";
const SECOND_HANDLER = "com.etendoerp.advpaymentmngt.actionHandler.PaymentExecutionProcessActionHandler";
const PAYMENT_PICK_GRID = "payment_pick";
const SEVERITY_SUCCESS = "success";
const SEVERITY_ERROR = "error";
const GENERIC_ERROR = "Error executing the process";

const refreshPaymentGrid = () => {
  OB.Utilities.Action.executeJSON([{ refreshGrid: {} }, { refreshGridParameter: { gridName: PAYMENT_PICK_GRID } }]);
};

const handleExecutionResponse = (data) => {
  if (!data) {
    messageBar.setMessage(SEVERITY_ERROR, null, GENERIC_ERROR);
    return;
  }
  if (data.success) {
    refreshPaymentGrid();
    messageBar.setMessage(SEVERITY_SUCCESS, null, data.message);
  } else {
    messageBar.setMessage(SEVERITY_ERROR, null, data.error || GENERIC_ERROR);
  }
};

OB.Utilities.Action.set(EAPM_POPUP_ACTION, async (actionData) => {
  const collected = await openDynamicForm({
    title: actionData.executionProcessName,
    fields: actionData.processParameters,
  });
  if (!collected) {
    return;
  }
  OB.RemoteCallManager.call(
    SECOND_HANDLER,
    { _params: actionData, processParameters: collected },
    {},
    (rpcResponse, data) => handleExecutionResponse(data)
  );
});

return {};

async (process, context) => {
  const selectedRecords = context.selectedRecords;
  const tabId = context?.tabId || '';

  const values = Object.values(selectedRecords);

  const documentStatuses = Array.from(new Set(values.map(record => record.documentStatus)));

  const isProcessing = values.some(record => (record.processing || record.isprocessing || 'N') === 'Y') ? 'Y' : '';

  const queryParams = new URLSearchParams({
    _action: `${process.javaClassName}Defaults`,
  });

  const payload = {
    documentStatuses,
    isProcessing,
    tabId,
  };

  const { ok, data, status } = await Metadata.kernelClient.post(`?${queryParams}`, payload);

  if (!ok) {
    throw new Error(`HTTP error! status: ${status}`);
  }

  return {
    DocAction: data.actions,
  };
}

async (process, params) => {
  const recordIds = params.recordIds;
  const docAction = params.DocAction;
  const windowId = params.windowId;
  const entityName = params.entityName;

  const queryParams = new URLSearchParams({
    processId: process.id,
    windowId,
    _action: 'com.smf.jobs.defaults.ProcessOrders',
  });

  const payload = {
    recordIds,
    _buttonValue: params.buttonValue,
    _params: {
      DocAction: docAction,
    },
    _entityName: entityName,
  };

  const { ok, data, status } = await Metadata.kernelClient.post(`?${queryParams}`, payload);

  if (!ok) {
    throw new Error(`HTTP error! status: ${status}`);
  }

  return data;
}

columnDataChange.oldValue:
async (_processDefinition, { selectedRecords, parentRecord }) => {
  let initialTotalPay = 0;


  // Add if there are already records selected by default
  if (selectedRecords && selectedRecords.length > 0) {
    for (let i = 0; i < selectedRecords.length; i++) {
        const payment = selectedRecords[i].realpayment || selectedRecords[i].realPayment || 0;
        initialTotalPay += parseFloat(payment);
    }
  }

  // Extract the dueDate from the parent record
  const remittanceDueDate = parentRecord?.inpduedate || parentRecord?.dueDate;

  // Initial Payload
  const loadPayload = {
    "total count": initialTotalPay
  };

  // Map the injected Criteria in onLoadGrid (expectedDate <= remittanceDueDate)
  if (remittanceDueDate) {
    // The grid in the parameter definition is called "pending payments" (dBColumnName)
    const gridKey = "pending payments";
    console.log("gridKey: ", gridKey);

    loadPayload._filterExpressions = {
      [gridKey]: {
        expectedDate: {
          operator: "lessOrEqual",
          value: `To - ${remittanceDueDate}`
        }
      }
    };
  }

  return loadPayload;
}

columnDataChange.newValue:
async (process, view) => {
  const GRID_KEY = 'pending payments';
  const remittanceDueDate = view.getContextInfo().inpduedate;
  if (!remittanceDueDate) {
    return;
  }
  return {
    _filterExpressions: {
      [GRID_KEY]: {
        expectedDate: { operator: 'lessOrEqual', value: remittanceDueDate }
      }
    }
  };
}

columnDataChange.oldValue:
{
  id: "OB_REM_ProcessPP_Rules",
  compute: (context, util) => {
    const gridKey = "pending payments";

    const selectedRecords = (context._gridSelection && context._gridSelection[gridKey]) 
      ? context._gridSelection[gridKey]._selection 
      : context._selectedRecords || [];

    let totalPay = 0;

    if (selectedRecords) {
      for (let i = 0; i < selectedRecords.length; i++) {
        const rawPayment = selectedRecords[i].realpayment || selectedRecords[i].realPayment || 0;
        const paymentAmount = parseFloat(rawPayment);
        totalPay += isNaN(paymentAmount) ? 0 : paymentAmount;
      }
    }

    const finalValueString = totalPay.toFixed(2);

    return {
      "total count": finalValueString,
      "totalCount": finalValueString,
      "inptotal count": finalValueString
    };
  }
}

columnDataChange.newValue:
async (process, payload) => {
  try {
    const selectedRecords = payload.selectedRecords || [];

    if (!selectedRecords || selectedRecords.length === 0) {
      return {};
    }

    return {
      autoSelectConfig: {
        table: 'order_invoice',
        logic: {
          field: 'salesOrderNo',
          operator: '=',
          valueFromContext: 'documentNo'
        }
      }
    };
  } catch (error) {
    console.error('Error en onLoad:', error);
    return {};
  }
}

export const AddPaymentRulesGeneric = {
  id: "APRM_ADD_PAYMENT_V1",

  // Synchronous UI-level reactive rules, applied by WindowReferenceGrid in the
  // same React update cycle as the cell edit. Mirrors classic
  // OB.APRM.AddPayment.glItemAmountOnChange: in the GL Items grid, received_in
  // and paid_out are mutually exclusive — entering a non-zero value in one
  // forces the other to 0 on the same row.
  //
  // Declaring both DB (received_in/paid_out) and HQL (receivedIn/paidOut)
  // pairs keeps matching robust because GridCellEditor mirrors writes to both
  // keys on row.original, but onRecordChange only carries the HQL key.
  fieldInteractions: {
    glitem: {
      mutualExclusion: [
        ["received_in", "paid_out"],
        ["receivedIn", "paidOut"],
      ],
    },
  },

  compute: (_context, util) => {
    const actualPayment = util.valNum("actual_payment", "actualPayment", "ActualPayment");
    const invoices = util.getGridItems(["amount", "outstandingAmount"], ["order_invoice"]);

    const trxtype = util.valStr("trxtype");
    let isSOTrx = util.valBool("issotrx", "isSOTrx");
    if (!isSOTrx && trxtype === "RCIN") {
      isSOTrx = true;
    }

    const usedCreditValue = util.valNum("used_credit", "usedCredit", "UsedCredit");
    const conversionRate = util.valNum("conversion_rate", "conversionRate", "finPaymentRate") || 1;
    const currencyPrecision = util.valNum("currency_precision", "currencyPrecision") || 2;
    const bslamount = util.valNum("bslamount", "bslAmount", "bankStatementLineAmount");

    const receivedFrom = util.valStr("received_from", "receivedFrom", "c_bpartner_id");
    const overpaymentAction = util.valStr("overpayment_action", "overpaymentAction");
    const currencyId = util.valStr("currency_id", "currencyId", "c_currency_id");
    const currencyToId = util.valStr("currency_to_id", "currencyToId", "finPaymentCurrency");

    // "glitem" is the dBColumnName of the Window Reference parameter for GL Items.
    // We read _allRows (not _selection) because the grid has obuiappShowSelect=false:
    // every row is meaningful input, equivalent to OB.APRM.AddPayment.updateGLItemsTotal
    // iterating grid.data.allRows in the classic UI.
    const glItems = util.getAllGridRows(
      ["received_in", "paid_out", "receivedIn", "paidOut"],
      ["glitem"]
    );

    const creditItems = util.getGridItems(["paymentAmount", "outstandingAmount"], ["credit_to_use"]);
    let usedCreditCalculated = util.num(0);

    if (creditItems.length > 0) {
        for (const item of creditItems) {
            const pAmt = util.num(item.paymentAmount);
            if (pAmt.eq(0)) {
                item.paymentAmount = item.outstandingAmount;
            }
        }
        usedCreditCalculated = util.sum(creditItems, "paymentAmount");
    } else {
        usedCreditCalculated = util.num(usedCreditValue || 0);
    }

    const finalUsedCredit = usedCreditCalculated;
    const totalOutstanding = util.sum(invoices, "outstandingAmount");

    if (invoices.length > 0) {
        const totalToDistribute = util.num(actualPayment || 0).plus(finalUsedCredit);
        util.distributeAmount(invoices, totalToDistribute);
    }

    const amountInvOrds = util.sum(invoices, "amount");

    const amountGLItems = glItems.reduce((total, row) => {
      // Accept both DB ("received_in"/"paid_out") and HQL ("receivedIn"/"paidOut")
      // shapes — the new UI's GridCellEditor mirrors writes to both keys.
      const receivedIn = util.num(row.received_in ?? row.receivedIn ?? 0);
      const paidOut = util.num(row.paid_out ?? row.paidOut ?? 0);
      if (isSOTrx) {
        return total.plus(receivedIn).minus(paidOut);
      }
      return total.minus(receivedIn).plus(paidOut);
    }, util.num(0));

    const usedCredit = finalUsedCredit;
    const expectedPayment = totalOutstanding;
    const total = util.num(amountInvOrds).plus(amountGLItems);

    const actualPaymentBD = util.num(actualPayment);
    const difference = actualPaymentBD.plus(usedCredit).minus(total);

    let expectedDifference = expectedPayment.plus(usedCredit).minus(amountInvOrds);
    if (expectedDifference.eq(0)) {
      expectedDifference = difference;
    }

    let _convertedAmount = actualPaymentBD;
    const isMultiCurrency = currencyId && currencyToId && currencyId !== currencyToId;

    if (isMultiCurrency && conversionRate) {
      _convertedAmount = util.convert(actualPayment, conversionRate, 1, currencyPrecision);
    }

    const bslAmountBD = util.num(bslamount);
    const hasBslAmount = !bslAmountBD.eq(0);

    if (hasBslAmount && isMultiCurrency && conversionRate) {
      _convertedAmount = bslAmountBD.abs();
    }

    const negativeAmount = invoices
      .filter((inv) => util.num(inv.outstandingAmount).lt(0))
      .reduce((acc, inv) => {
        return acc.plus(Math.abs(inv.outstandingAmount));
      }, util.num(0));

    const totalWriteOffAmount = invoices.reduce((total, inv) => {
      if (!inv.writeoff) return total;
      const outstanding = util.num(inv.outstandingAmount);
      const amount = util.num(inv.amount || 0);
      const writeoffAmt = outstanding.minus(amount);
      return total.plus(writeoffAmt);
    }, util.num(0));

    const fmt = (n) => n.toFixed(2);

    return {
      expected_payment: fmt(expectedPayment),
      Expected_Payment: fmt(expectedPayment),
      expectedPayment: fmt(expectedPayment),
      "Expected Payment": fmt(expectedPayment),

      amount_inv_ords: fmt(amountInvOrds),
      amountInvOrds: fmt(amountInvOrds),
      AmountInvOrds: fmt(amountInvOrds),
      "Amount on Invoices and/or Orders": fmt(amountInvOrds),
      "Amount Inv Ords": fmt(amountInvOrds),

      amount_gl_items: fmt(amountGLItems),
      amountGlItems: fmt(amountGLItems),
      AmountGlItems: fmt(amountGLItems),
      "Amount on GL Items": fmt(amountGLItems),

      total: fmt(total),
      Total: fmt(total),
      TOTAL: fmt(total),

      used_credit: fmt(usedCredit),
      usedCredit: fmt(usedCredit),
      "Used Credit": fmt(usedCredit),

      difference: fmt(difference),
      Difference: fmt(difference),

      expectedDifference: fmt(expectedDifference),
      ExpectedDifference: fmt(expectedDifference),
      expected_difference: fmt(expectedDifference),
      "There is a difference of": fmt(expectedDifference),

      overpayment_action: difference.gt(0) ? "CR" : "",
      overpayment_action_display_logic: difference.gt(0) ? "Y" : "N",

      _computed: {
        totalOutstanding: totalOutstanding.toNumber(),
        negativeAmount: negativeAmount.toNumber(),
        totalWriteOffAmount: totalWriteOffAmount.toNumber(),
        hasBslAmount,
        selectedInvoicesCount: invoices.length,
        hasReceivedFrom: !!receivedFrom,
        amountGLItems: amountGLItems.toNumber(),
        usedCredit: usedCredit.toNumber(),
      },

      order_invoice: invoices,
      credit_to_use: creditItems,
    };
  },

  validate: (_context, computed, util) => {
    const validations = [];

    const actualPayment = util.valNum("actual_payment", "actualPayment", "ActualPayment");
    const overpaymentAction = util.valStr("overpayment_action", "overpaymentAction");

    const _comp = computed._computed || {};
    const total = typeof computed.total === "string" ? Number.parseFloat(computed.total) : computed.total || 0;

    const actualBD = util.num(actualPayment);
    const totalBD = util.num(total);

    if (overpaymentAction && !_comp.hasReceivedFrom) {
      validations.push({
        id: "APRM_CREDIT_NO_BPARTNER",
        isValid: false,
        message: "APRM_CreditWithoutBPartner",
        severity: "error",
      });
    }

    if (totalBD.gt(actualBD.plus(_comp.usedCredit || 0))) {
      validations.push({
        id: "APRM_MORE_ALLOCATED",
        isValid: false,
        message: "APRM_JSMOREAMOUTALLOCATED",
        severity: "error",
      });
    }

    const invoices = computed.order_invoice || [];
    for (const invoice of invoices) {
       const amt = util.num(invoice.amount);
       const out = util.num(invoice.outstandingAmount);
       if (amt.minus(out).gt(0.01)) {
           validations.push({
               id: "AMOUNT_EXCEEDS_OUTSTANDING",
               isValid: false,
               message: "APRM_JSMOREAMOUTALLOCATED",
               severity: "error",
               context: { id: invoice.id }
           });
       }
    }

    return validations;
  },
};

async (process, view) => {
  const AMOUNT_NOT_EQUALS = 'OBFBPS_Err_AmountNotEquals';
  const SELECT_INVOICE = 'OBFBPS_Err_SelectInvoice';
  const purchaseInvoiceGrid = getInvoiceGrid(view, PURCHASE_INVOICE);
  const salesInvoiceGrid = getInvoiceGrid(view, SALES_INVOICE);
  const amountPurchase = getSelectedAmount(purchaseInvoiceGrid);
  const amountSales = getSelectedAmount(salesInvoiceGrid);
  view.theForm.getItem(PURCHASE_AMOUNT).setValue(amountPurchase);
  view.theForm.getItem(SALES_AMOUNT).setValue(amountSales);
  const exceedInvoice = checkAmounts(view, purchaseInvoiceGrid, salesInvoiceGrid);
  if (exceedInvoice) {
    return { severity: 'error', text: OB.I18N.getLabel(AMOUNT_EXCEED_PENDING, [exceedInvoice]) };
  }
  if (amountPurchase !== amountSales) {
    const text = OB.I18N.getLabel(AMOUNT_NOT_EQUALS);
    view.messageBar.setMessage(isc.OBMessageBar.TYPE_ERROR, null, text);
    return { severity: 'error', text };
  }
  if (amountPurchase === 0) {
    const text = OB.I18N.getLabel(SELECT_INVOICE);
    view.messageBar.setMessage(isc.OBMessageBar.TYPE_ERROR, null, text);
    return { severity: 'error', text };
  }
  return undefined;
}

const PURCHASE_INVOICE = 'OBFBPS_PurchaseInvoice';
const SALES_INVOICE = 'OBFBPS_SalesInvoice';
const PURCHASE_AMOUNT = 'OBFBPS_PurchaseAmount';
const SALES_AMOUNT = 'OBFBPS_SalesAmount';
const PEND_AMOUNT = 'OBFBPS_PendAmount';
const AMOUNT_EXCEED_PENDING = 'OBFBPS_Err_AmountExceedPending';
const SETTLEMENT_AMOUNT = 'settlementAmount';

const getInvoiceGrid = (view, paramName) => view.theForm.getItem(paramName).canvas.viewGrid;

const getSelectedAmount = grid => {
  let amount = BigDecimal.prototype.ZERO;
  const records = grid.getSelectedRecords();
  records.forEach(record => {
    const index = grid.getRecordIndex(record);
    const item = grid.getEditValues(index);
    const editedAmount = item && item[SETTLEMENT_AMOUNT];
    const value = editedAmount ? editedAmount : record[SETTLEMENT_AMOUNT] || 0;
    amount = amount.add(new BigDecimal(String(value)));
  });
  return Number(amount.toString());
};

const checkInvoiceAmount = grid => {
  let result = null;
  const records = grid.getSelectedRecords();
  records.every(record => {
    const index = grid.getRecordIndex(record);
    const item = grid.getEditValues(index);
    const editedAmount = item && item[SETTLEMENT_AMOUNT];
    if (editedAmount && editedAmount > record.amount) {
      result = record.documentNo;
      return false;
    }
    return true;
  });
  return result;
};

const checkAmounts = (view, purchaseInvoiceGrid, salesInvoiceGrid) => {
  view.messageBar.hide();
  const grids = [purchaseInvoiceGrid, salesInvoiceGrid];
  for (let i = 0; i < grids.length; i++) {
    const invoice = checkInvoiceAmount(grids[i]);
    if (invoice) {
      const text = OB.I18N.getLabel(AMOUNT_EXCEED_PENDING, [invoice]);
      view.messageBar.setMessage(isc.OBMessageBar.TYPE_ERROR, null, text);
      return invoice;
    }
  }
  return null;
};

const setAmounts = view => {
  const purchaseInvoiceGrid = getInvoiceGrid(view, PURCHASE_INVOICE);
  const salesInvoiceGrid = getInvoiceGrid(view, SALES_INVOICE);
  const amountPurchase = getSelectedAmount(purchaseInvoiceGrid);
  const amountSales = getSelectedAmount(salesInvoiceGrid);
  view.theForm.getItem(PURCHASE_AMOUNT).setValue(amountPurchase);
  view.theForm.getItem(SALES_AMOUNT).setValue(amountSales);
  view.theForm.getItem(PEND_AMOUNT).setValue(amountSales - amountPurchase);
};

// Live selection-toggle recompute. The module body runs once per modal open, so
// recomputeAmounts is a single stable reference; passing that same reference to
// every grid's grid.onSelectionToggle lets the substrate's reference-dedup
// collapse repeated registrations across grid reloads. It reads the latest view
// captured on grid load, so it always recomputes against a current view proxy.
let lastView = null;
const setLastView = view => { lastView = view; };
const recomputeAmounts = () => { if (lastView) setAmounts(lastView); };

// Live recompute when the user edits a row's Settlement Amount cell. Ported
// 1:1 from classic amountChange(item, view, form, grid): recompute every total
// (setAmounts) and revalidate the over-pending banner (checkAmounts), ignoring
// the return value exactly as classic did. Registered via grid.setColumnOnChange
// under SETTLEMENT_AMOUNT, so it is one stable module-scope reference reused by
// both grids' on_grid_load (re-registration is idempotent by column key).
const onSettlementAmountChange = (item, view, form, grid) => {
  setAmounts(view);
  const purchaseInvoiceGrid = getInvoiceGrid(view, PURCHASE_INVOICE);
  const salesInvoiceGrid = getInvoiceGrid(view, SALES_INVOICE);
  checkAmounts(view, purchaseInvoiceGrid, salesInvoiceGrid);
};

return {
  PURCHASE_INVOICE,
  SALES_INVOICE,
  PURCHASE_AMOUNT,
  SALES_AMOUNT,
