(grid, view, parameters) => {
  try {
    const rows = grid.data.allRows;
    rows.forEach((row, index) => {
      const total = sumAccountAmount(row.id);
      if (total !== null) {
        grid.setEditValue(index, AMOUNT_COLUMN, total);
      }
    });
  } catch (error) {
    console.error('Error during matching:', error);
  }
}

(item, view, form) => {
  const DIMENSION_FIELDS = [
    "FromAccount",
    "ToAccount",
    "BusinessPartner",
    "product",
    "c_project",
    "groupBy",
    "includeZeroFigures",
  ];
  const SUMMARY_LEVEL = "S";

  const setVisibility = (fieldNames, visible) => {
    fieldNames.forEach((fieldName) => {
      const field = form.getItem(fieldName);
      if (field) {
        if (visible) {
          field.show();
        } else {
          field.hide();
        }
      }
    });
  };

  const accountLevelItem = form.getItem("AccountLevel");
  const accountLevel = accountLevelItem ? accountLevelItem.getValue() : null;

  setVisibility(DIMENSION_FIELDS, accountLevel === SUMMARY_LEVEL);
}

(item, view, form, grid) => {
  const RECEIVED_IN = "Received In";
  const PAID_OUT = "Paid Out";

  const itemName = item.name;
  const itemValue = item.getValue();

  if (itemName === RECEIVED_IN) {
    form.getItem(PAID_OUT).setValue(!itemValue);
  }

  if (itemName === PAID_OUT) {
    form.getItem(RECEIVED_IN).setValue(!itemValue);
  }
}

(item, view, form, grid) => {
  const HANDLER =
    'org.openbravo.advpaymentmngt.actionHandler.FundsTransferOnChangeDepositToActionHandler';

  const callback = (response, data) => {
    if (!data || !data.currencyID) {
      return;
    }
    const currencyTo = form.getItem('c_currency_to_id');
    currencyTo.setValueFromRecord({
      id: data.currencyID,
      _identifier: data.currencyISO
    });
    form.redraw();
  };

  OB.RemoteCallManager.call(HANDLER, { accountID: item.getValue() }, {}, callback);
}

